import { jsPDF } from "jspdf"

export function import_EncodeSansCond_Med() {
  var font = "";
  var callAddFont = function () {
    this.addFileToVFS( "EncodeSansCondensed-Medium-normal.ttf", font );
    this.addFont( "EncodeSansCondensed-Medium-normal.ttf", "EncodeSansCondensed-Medium", "normal" );
  };
  jsPDF.API.events.push( [ "addFonts", callAddFont ] )
}
